INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('df43a24c-40c2-478d-8598-c9023530b542', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'What does moderate severity mean?', 'A moderate severity caries means that the decay is a bit more advanced, but it''s still in the early stages. It might need some treatment, like a filling, to prevent it from getting worse. Let''s schedule an appointment with your dentist to discuss the best plan for you, and don''t worry, they can help you take care of it!
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('4ac6192e-be11-42a7-8d05-ce96a2ad34e7', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'what does moderate severity mean', 'When we say moderate severity, it means that the cavity is bigger than a small one, but not as big as a really big one. It''s at a stage where it might need a filling to prevent it from getting worse. It''s great that we caught it early, so you can see your dentist and get a proper assessment and treatment to keep your teeth healthy. Let''s schedule an appointment with your dentist to discuss the next steps.
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('a5dd0aa4-9c91-4493-99ba-4be4b0abade9', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'Hi', 'Hi there, I''m happy to help you understand your dental scan results. It looks like the scan detected 17 areas of tooth decay, with some being mild, moderate, or severe. Don''t worry, this is just a starting point for your dentist to assess and create a personalized treatment plan - it''s great that you''re taking proactive steps to prioritize your oral health!
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('045f0c89-57fa-46ec-9884-348f26a1785f', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'Will you book an appointment with the dentist', 'Based on your dental scan results, it looks like you have a few areas of tooth decay, with some being more severe than others. The good news is that we can work with your dentist to get you the treatment you need to keep your teeth healthy. I recommend booking an appointment with your dentist as soon as possible to get a more detailed examination and create a personalized plan to address these issues.
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('9351b8a6-5b3d-492c-b207-588a43f2d7e9', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'Hello', 'Hello! Your dental scan results show that you have 17 areas where bacteria might be causing problems, known as cavities. Three are mild, seven are moderate, and seven are quite severe. It''s great that you''re taking proactive steps by getting this scan – now, it''s time to schedule an appointment with your dentist to discuss the next steps and get a proper examination.
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('63d14b50-c7e7-4cc2-89cf-e0185b34c0c6', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'So What I have to do', 'Your scan results show that you have 17 areas of tooth decay, ranging from mild to severe. Don''t worry, this is a common issue, and we can work together to address it. I recommend scheduling an appointment with your dentist as soon as possible to get a more detailed evaluation and develop a plan to fix these issues.
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('7baf01b1-2572-4b7d-8d45-77ef2272bc7f', '327f803e-4640-4f3d-8b57-ba80ada72b11', NULL, 'Will you answer in other domains also or in only about dental caries', 'I''d be happy to help you understand your dental scan results in simple terms. I can also provide information on other dental-related topics, such as oral health, gum health, or even discuss general dental care tips. However, if you have specific questions about your caries (tooth decay), I''ll do my best to break it down for you. Let''s focus on what the scan results mean and what steps to take next.
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('b0c242bb-52e9-4c80-8b93-09471aca4077', '2fd8fdd6-ac0e-479c-8071-4e3c5add7581', NULL, 'Give about my scan results', 'Your scan results show that you have 9 areas of tooth decay, with 4 being mild, 1 moderate, and 4 being severe. This means that you have some cavities that need to be treated to prevent further damage. It''s great that you''re taking proactive steps to understand your oral health - now it''s time to schedule a visit with your dentist to discuss treatment options and create a plan to get your teeth healthy and strong again.
INSERT INTO public.chat_messages (id, user_id, detection_id, user_message, bot_response, created_at) VALUES ('87324aeb-d53b-4eb2-be6b-fb06ca7259a3', '2fd8fdd6-ac0e-479c-8071-4e3c5add7581', NULL, 'Give about my scan results', 'Your latest dental scan results show that you have a total of 9 areas of tooth decay, with 4 being mild, 1 moderate, and 4 severe. This means that you have some cavities that may not be causing immediate pain, but it''s essential to address them before they get worse. I recommend scheduling an appointment with your dentist to discuss the best course of treatment and get started on restoring your oral health.
