INSERT INTO public.resources (id, title, description, content, category, resource_type, url, thumbnail_url, author, source, tags, is_featured, view_count, created_at, updated_at) VALUES ('57dcde09-1848-4421-9c63-7c6980d1ddcb', 'Tooth Decay (Cavities)', 'Comprehensive guide on dental caries from Mayo Clinic', 'Cavities are permanently damaged areas in the hard surface of your teeth that develop into tiny openings or holes. Cavities, also called tooth decay or caries, are caused by a combination of factors, including bacteria in your mouth, frequent snacking, sipping sugary drinks and not cleaning your teeth well.', 'Education', 'article', 'https://www.mayoclinic.org/diseases-conditions/cavities/symptoms-causes/syc-20352892', NULL, 'Mayo Clinic', 'Mayo Clinic', '{cavities,"tooth decay",prevention}', true, 0, '2026-01-02 16:16:40.202825+00', '2026-01-02 16:16:40.202825+00') ON CONFLICT DO NOTHING;
INSERT INTO public.resources (id, title, description, content, category, resource_type, url, thumbnail_url, author, source, tags, is_featured, view_count, created_at, updated_at) VALUES ('ffb862bc-0342-41e7-8132-967a08ac3dd5', 'Dental Plaque: What It Is and How to Remove It', 'Understanding and managing dental plaque', 'Plaque is a sticky film of bacteria that constantly forms on teeth. Bacteria in plaque produce acids after you eat or drink. These acids can destroy tooth enamel and cause cavities and gingivitis.', 'Education', 'article', 'https://www.colgate.com/en-us/oral-health/plaque-and-tartar/what-is-plaque', NULL, 'Colgate', 'Colgate Oral Care', '{plaque,bacteria,"oral hygiene"}', false, 0, '2026-01-02 16:16:40.202825+00', '2026-01-02 16:16:40.202825+00') ON CONFLICT DO NOTHING;
INSERT INTO public.resources (id, title, description, content, category, resource_type, url, thumbnail_url, author, source, tags, is_featured, view_count, created_at, updated_at) VALUES ('35c653b1-b2bc-4286-ab82-60262377c0b3', 'Gum Disease (Periodontal Disease)', 'Complete guide to gum disease prevention and treatment', 'Gum disease is an infection of the tissues that hold your teeth in place. It is typically caused by poor brushing and flossing habits that allow plaque to build up on the teeth and harden.', 'Education', 'article', 'https://www.nidcr.nih.gov/health-info/gum-disease', NULL, 'NIDCR', 'National Institute of Dental Research', '{"gum disease",periodontal,prevention}', true, 0, '2026-01-02 16:16:40.202825+00', '2026-01-02 16:16:40.202825+00') ON CONFLICT DO NOTHING;
INSERT INTO public.resources (id, title, description, content, category, resource_type, url, thumbnail_url, author, source, tags, is_featured, view_count, created_at, updated_at) VALUES ('1372fd6b-2133-41eb-b83c-011e13824f21', 'Tooth Enamel Erosion', 'How to protect your tooth enamel', 'Tooth enamel is the hard, outer surface layer of your teeth that serves to protect against tooth decay. Learn about causes of enamel erosion and how to prevent it.', 'Education', 'article', 'https://www.webmd.com/oral-health/guide/tooth-enamel-erosion-restoration', NULL, 'WebMD', 'WebMD', '{enamel,erosion,protection}', false, 0, '2026-01-02 16:16:40.202825+00', '2026-01-02 16:16:40.202825+00') ON CONFLICT DO NOTHING;
INSERT INTO public.resources (id, title, description, content, category, resource_type, url, thumbnail_url, author, source, tags, is_featured, view_count, created_at, updated_at) VALUES ('efa3a781-9e23-497b-8664-52ab658f589a', 'The Right Way to Brush Your Teeth', 'ADA approved brushing technique', 'Brush your teeth twice a day with a soft-bristled brush. The size and shape of your brush should fit your mouth allowing you to reach all areas easily. Replace your toothbrush every three to four months.', 'Hygiene', 'guide', 'https://www.mouthhealthy.org/en/az-topics/b/brushing-your-teeth', NULL, 'ADA', 'American Dental Association', '{brushing,technique,"daily care"}', true, 0, '2026-01-02 16:16:40.202825+00', '2026-01-02 16:16:40.202825+00') ON CONFLICT DO NOTHING;
INSERT INTO public.resources (id, title, description, content, category, resource_type, url, thumbnail_url, author, source, tags, is_featured, view_count, created_at, updated_at) VALUES ('f29cb3af-f2ad-4e95-a02b-00851baed2f3', 'Flossing: How to Floss Your Teeth', 'Step-by-step flossing guide', 'Use about 18 inches of floss wound around one of your middle fingers, with the rest wound around the opposite middle finger. Hold the floss tightly between your thumbs and forefingers and gently insert it between your teeth.', 'Hygiene', 'guide', 'https://www.mouthhealthy.org/en/az-topics/f/flossing', NULL, 'ADA', 'American Dental Association', '{flossing,interdental,cleaning}', true, 0, '2026-01-02 16:16:40.202825+00', '2026-01-02 16:16:40.202825+00') ON CONFLICT DO NOTHING;
